   410  /* An array with a number of elements. */
   411  template <typename Type, typename LenType=HBUINT16>
   412  struct ArrayOf
   413  {
   414    const Type *sub_array (unsigned int start_offset, unsigned int *pcount /* IN/OUT */) const
   415    {
   416      unsigned int count = len;
   417      if (unlikely (start_offset > count))
   418        count = 0;
   419      else
   420        count -= start_offset;
   421      count = MIN (count, *pcount);
   422      *pcount = count;
   423      return arrayZ + start_offset;
   424    }
